use std::time::Duration;
use chrono::Utc;
use crate::{domain::{device::Device,managed_workload::ManagedWorkload,managed_workload_operation::{ManagedWorkloadOperation,ManagedWorkloadOperationState,ManagedWorkloadDispatchState},managed_workload_prepare::{parse_prepare,fingerprint}},infrastructure::{managed_workload_trust::{trust_probe_command,parse_trust_probe,ACTION_ROOT},ssh::{RemoteExecutor,RemoteOutputLimits,SshTarget}},monitoring::maintenance_coordinator::{DeviceMaintenanceCoordinator,MaintenanceOperationKind},storage::{device_repository::{DeviceRepository,JsonDeviceRepository},managed_workload_repository::{ManagedWorkloadRepository,JsonManagedWorkloadRepository},managed_workload_operation_repository::JsonManagedWorkloadOperationRepository}};
const LIMITS:RemoteOutputLimits=RemoteOutputLimits{stdout:32*1024,stderr:16*1024}; const TIMEOUT:Duration=Duration::from_secs(15);
#[derive(Debug,Clone)] pub struct PreparedWorkload { pub operation:ManagedWorkloadOperation,pub change_count:u32 }
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum PrepareError { Unavailable, Conflict, Trust, Protocol, Transport, Persistence }
fn verification(w:&ManagedWorkload)->Vec<String>{let mut v=Vec::new();if let Some(p)=&w.compose_project{v.push(format!("compose:{p}"))}v.extend(w.required_compose_services.iter().map(|s|format!("service:{s}")));v.extend(w.required_service_health_ids.iter().map(|s|format!("health:{s}")));v}
fn target(device:&Device)->SshTarget{SshTarget{host:device.host.clone(),port:device.ssh_port,username:device.ssh_username.clone()}}
pub fn prepare_with(dir:&std::path::Path,workload_id:&str,executor:&dyn RemoteExecutor,coordinator:&DeviceMaintenanceCoordinator)->Result<PreparedWorkload,PrepareError>{let workloads=JsonManagedWorkloadRepository::new(dir).load();let w=workloads.workloads.into_iter().find(|w|w.id==workload_id).filter(|w|w.enabled).ok_or(PrepareError::Unavailable)?;let device=JsonDeviceRepository::new(dir).load_all().into_iter().find(|d|d.id==w.device_id).ok_or(PrepareError::Unavailable)?;let target=target(&device);let _claim=coordinator.try_claim(&w.device_id,MaintenanceOperationKind::WorkloadDeploy).ok_or(PrepareError::Conflict)?;let trust=executor.execute_bounded(&target,&trust_probe_command(&w.action_id).map_err(|_|PrepareError::Trust)?,TIMEOUT,LIMITS).map_err(|_|PrepareError::Transport)?;let action=parse_trust_probe(&w.action_id,&trust.stdout).map_err(|_|PrepareError::Trust)?;let command=format!("'{ACTION_ROOT}/{}' prepare",w.action_id);let reply=executor.execute_bounded(&target,&command,TIMEOUT,LIMITS).map_err(|_|PrepareError::Transport)?;let plan=parse_prepare(&reply.stdout).map_err(|_|PrepareError::Protocol)?;let fp=fingerprint(&w.id,w.config_revision,&action.sha256,&plan.target_revision,&verification(&w));let now=Utc::now().to_rfc3339();let op=ManagedWorkloadOperation{schema_version:1,id:uuid::Uuid::new_v4().to_string(),device_id:w.device_id,workload_id:w.id,action_id:w.action_id,config_revision:w.config_revision,trusted_action_digest:action.sha256,target_revision:plan.target_revision.as_str().into(),deployment_fingerprint:fp.0,transient_unit_id:None,dispatch_state:ManagedWorkloadDispatchState::NotAttempted,state:ManagedWorkloadOperationState::Prepared,created_at:now.clone(),prepared_at:Some(now),started_at:None,observation_deadline:None,completed_at:None,failure:None};JsonManagedWorkloadOperationRepository::new(dir).save(&op).map_err(|_|PrepareError::Persistence)?;Ok(PreparedWorkload{operation:op,change_count:plan.change_count})}
#[cfg(test)] mod tests { use super::*; use crate::{domain::{device::{Device,DeviceType},managed_workload::{ManagedWorkload,ManagedWorkloadFile}},infrastructure::ssh::{RemoteExecutionResult,SshError},storage::{device_repository::DeviceRepository,managed_workload_repository::ManagedWorkloadRepository,managed_workload_operation_repository::JsonManagedWorkloadOperationRepository}}; use std::{collections::VecDeque,sync::Mutex}; struct Script{replies:Mutex<VecDeque<RemoteExecutionResult>>,seen:Mutex<Vec<(String,String,u16,String)>>} impl RemoteExecutor for Script{fn execute(&self,t:&SshTarget,c:&str,_:Duration)->Result<RemoteExecutionResult,SshError>{self.seen.lock().unwrap().push((c.into(),t.host.clone(),t.port,t.username.clone()));Ok(self.replies.lock().unwrap().pop_front().unwrap())}} fn ok(s:String)->RemoteExecutionResult{RemoteExecutionResult{exit_code:Some(0),stdout:s,stderr:"raw-secret".into(),duration_ms:1,timed_out:false}} #[test] fn fixed_prepare_persists_and_releases_claim(){let d=tempfile::tempdir().unwrap();let device=Device{id:"pi5".into(),name:"p".into(),host:"host.example".into(),ssh_port:2222,ssh_username:"deploy".into(),description:None,device_type:DeviceType::RaspberryPi,monitoring_enabled:true,refresh_interval_seconds:None,notify_on_device_offline:true,notify_on_container_failure:true,notify_on_container_unhealthy:true,services:vec![],created_at:"x".into(),updated_at:"x".into()};JsonDeviceRepository::new(d.path()).save_all(&[device]).unwrap();let w=ManagedWorkload{id:"finance".into(),device_id:"pi5".into(),name:"Finance".into(),action_id:"personal-finance".into(),compose_project:Some("finance".into()),required_compose_services:vec!["app".into()],required_service_health_ids:vec![],enabled:true,config_revision:1};JsonManagedWorkloadRepository::new(d.path()).save(&ManagedWorkloadFile{schema_version:1,workloads:vec![w]}).unwrap();let e=Script{replies:Mutex::new(VecDeque::from(vec![ok(format!("PIHUB_M17_TRUST=trusted\nPIHUB_M17_ACTION_DIGEST={}\n","a".repeat(64))),ok(format!(r#"{{"protocolVersion":1,"status":"ready","currentRevision":"{}","targetRevision":"{}","changeCount":2}}"#,"b".repeat(40),"c".repeat(40)))])),seen:Mutex::new(vec![])};let c=DeviceMaintenanceCoordinator::new();let r=prepare_with(d.path(),"finance",&e,&c).unwrap();assert_eq!(r.operation.target_revision,"c".repeat(40));assert_eq!(r.operation.trusted_action_digest,"a".repeat(64));let seen=e.seen.lock().unwrap();assert_eq!(seen.len(),2);assert_eq!(seen[0].1,"host.example");assert_eq!(seen[0].2,2222);assert_eq!(seen[0].3,"deploy");assert!(seen[1].0.ends_with("personal-finance' prepare"));assert!(!seen.iter().any(|x|x.0.contains("apply")||x.0.contains("systemd-run")));drop(seen);assert_eq!(JsonManagedWorkloadOperationRepository::new(d.path()).get("pi5","finance"),Some(r.operation));assert!(c.try_claim("pi5",MaintenanceOperationKind::WorkloadDeploy).is_some());}}
